export function FluidLayout({
  width = {{width}},
  minSize = {{minSize}},
  maxSize = {{maxSize}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 18, boxSizing: "border-box" }}>
        <p style={{ margin: 0, fontWeight: 800, fontFamily: "system-ui, sans-serif", lineHeight: 1.15, fontSize: `clamp(${minSize}px, 8cqw, ${maxSize}px)`, color: accent }}>Scales smoothly, no jumps</p>
      </div>
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#241430aa" }}>{width}px container &mdash; font uses clamp({minSize}px, 8cqw, {maxSize}px)</p>
    </div>
  );
}
